// drive — one screen: the level going in against the level coming out, read off the taps, not guessed.

const IN = "#6b6b6b";
const OUT = "#ff6a1a";
const INK = "#ffffff";
const FONT = "8px ui-monospace, monospace";
const FLOOR = -48;

const db = (a) => (a > 1e-5 ? 20 * Math.log10(a) : -100);
const level = (a) => Math.max(0, Math.min(1, (db(a) - FLOOR) / -FLOOR));
const last = (arr) => (Array.isArray(arr) && arr.length > 0 ? Number(arr[arr.length - 1]) || 0 : 0);

/** One tap's recent history as a line, newest at the right edge. */
function trace(ctx, arr, x0, top, w, h, color) {
  const n = Array.isArray(arr) ? Math.min(arr.length, 160) : 0;
  if (n < 2) return;
  const start = arr.length - n;
  ctx.strokeStyle = color;
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let i = 0; i < n; i++) {
    const px = x0 + (i / (n - 1)) * w;
    const py = top + h * (1 - level(Number(arr[start + i]) || 0));
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.stroke();
}

export default {
  io(lcd) {
    const { ctx, width: W, height: H, input, output } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);
    ctx.font = FONT;
    ctx.textBaseline = "alphabetic";

    const pad = 5;
    const top = 13;
    const h = Math.max(1, H - top - pad);
    const barW = 5;
    const bars = barW * 2 + 4;
    const w = Math.max(1, W - pad * 3 - bars);
    const hasIn = Array.isArray(input) && input.length > 0;
    const hasOut = Array.isArray(output) && output.length > 0;

    ctx.strokeStyle = IN;
    ctx.lineWidth = 1;
    ctx.strokeRect(pad + 0.5, top + 0.5, w - 1, h - 1);

    if (!hasIn && !hasOut) {
      ctx.fillStyle = IN;
      ctx.textAlign = "center";
      ctx.fillText("NO SIGNAL", pad + w / 2, top + h / 2 + 3);
    } else {
      trace(ctx, input, pad, top, w, h, IN);
      trace(ctx, output, pad, top, w, h, OUT);
    }

    const inNow = last(input);
    const outNow = last(output);
    const bx = pad * 2 + w;
    ctx.fillStyle = IN;
    const hi = h * level(inNow);
    ctx.fillRect(bx, top + h - hi, barW, hi);
    ctx.fillStyle = OUT;
    const ho = h * level(outNow);
    ctx.fillRect(bx + barW + 4, top + h - ho, barW, ho);

    ctx.textAlign = "left";
    ctx.fillStyle = IN;
    ctx.fillText("IN", pad, 9);
    ctx.fillStyle = OUT;
    ctx.fillText("OUT", pad + 16, 9);
    if (inNow > 1e-4 && outNow > 1e-4) {
      const diff = db(outNow) - db(inNow);
      ctx.textAlign = "right";
      ctx.fillStyle = INK;
      ctx.fillText(`${diff >= 0 ? "+" : ""}${diff.toFixed(1)} DB`, W - pad, 9);
    }
  },
};

// bass-drive — two pictures side by side: how hard the drive bends the signal, and where the four bands sit.

const DRIVE = "#ff6a1a";
const TONE = "#3ec96b";
const GRID = "#6b6b6b";
const FONT = "8px ui-monospace, monospace";

const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);

/** The drive's transfer curve: a soft clip that bends harder as Drive rises — its shape, not Bass Drive's exact law. */
function transfer(ctx, x0, y0, w, h, drive) {
  const k = 1 + drive * 9;
  const norm = Math.tanh(k) || 1;
  ctx.strokeStyle = GRID;
  ctx.lineWidth = 1;
  ctx.beginPath();
  // The straight line a clean signal would follow, for the bend to be read against.
  ctx.moveTo(x0, y0 + h);
  ctx.lineTo(x0 + w, y0);
  ctx.stroke();
  ctx.strokeStyle = DRIVE;
  ctx.beginPath();
  for (let i = 0; i <= 48; i++) {
    const x = -1 + (2 * i) / 48;
    const y = Math.tanh(k * x) / norm;
    const px = x0 + ((x + 1) / 2) * w;
    const py = y0 + h - ((y + 1) / 2) * h;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.stroke();
}

/** The four bands as a smooth tone shape across low to presence — where each knob pushes, not a measured response. */
function tone(ctx, x0, y0, w, h, bands) {
  const mid = y0 + h / 2;
  ctx.strokeStyle = GRID;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(x0, Math.round(mid) + 0.5);
  ctx.lineTo(x0 + w, Math.round(mid) + 0.5);
  ctx.stroke();
  const at = (i) => mid - (clamp01(bands[i]) - 0.5) * h * 0.9;
  const xs = bands.map((_, i) => x0 + ((i + 0.5) / bands.length) * w);
  ctx.strokeStyle = TONE;
  ctx.beginPath();
  ctx.moveTo(x0, at(0));
  for (let i = 0; i < bands.length; i++) {
    const prevX = i === 0 ? x0 : xs[i - 1];
    const prevY = i === 0 ? at(0) : at(i - 1);
    const cx = (prevX + xs[i]) / 2;
    ctx.bezierCurveTo(cx, prevY, cx, at(i), xs[i], at(i));
  }
  ctx.lineTo(x0 + w, at(bands.length - 1));
  ctx.stroke();
  ctx.fillStyle = TONE;
  for (let i = 0; i < bands.length; i++) {
    ctx.beginPath();
    ctx.arc(xs[i], at(i), 2, 0, Math.PI * 2);
    ctx.fill();
  }
}

export default {
  shape(lcd) {
    const { ctx, width: W, height: H, params } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);
    ctx.font = FONT;

    const pad = 6;
    const top = 13;
    const h = Math.max(1, H - top - pad);
    const left = Math.max(1, Math.min(h * 1.4, W * 0.35));
    const drive = clamp01(params["Drive"] ?? 0.5);
    const bands = ["Low", "Mid", "High", "Presnce"].map((n) => params[n] ?? 0.5);

    transfer(ctx, pad, top, left, h, drive);
    tone(ctx, pad * 3 + left, top, Math.max(1, W - left - pad * 4), h, bands);

    ctx.textAlign = "left";
    ctx.fillStyle = DRIVE;
    ctx.fillText(`DRIVE ${Math.round(drive * 100)}`, pad, 9);
    ctx.fillStyle = TONE;
    ctx.fillText("LOW  MID  HIGH  PRES", pad * 3 + left, 9);
  },
};

